mits"], "customer_explanation_el": "Αν ο τοίχος αφήνει πούδρα στο χέρι, δεν περνάμε απλώς νέο χρώμα. Αφαιρούμε την κιμωλίαση και ελέγχουμε αν η επιφάνεια έχει γίνει σταθερή πριν επιλεγεί αστάρι.", "humidity_considerations": [], "suitable_solution_types": [], "compatibility_principles": ["Stabilising primer is not a universal sealer; exact use must follow selected system instructions"], "tool_categories_required": ["stiff_brush_or_washing", "scraper", "abrasive", "dust_removal", "roller", "brush"], "ventilation_requirements": [], "unsuitable_solution_types": [], "temperature_considerations": [], "condensation_considerations": [], "inspection_after_application": ["Έλεγχος αν η νέα στρώση παραμένει σταθερή μετά την ωρίμανση"], "protection_materials_required": ["ground_and_opening_protection"], "substrate_moisture_considerations": []}, {"id": "b825a11b-a846-4ff6-b636-6fae2853c43f", "published": true, "substrate": "exterior render/masonry", "created_at": "2026-09-21T09:16:37.183394+00:00", "updated_at": "2026-09-21T09:16:37.183394+00:00", "ppe_general": ["PPE σύμφωνα με εργασίες προετοιμασίας/SDS"], "primer_role": [], "reviewed_at": "2026-09-21T09:16:37.183394+00:00", "scenario_key": "paint_exterior_hairline_cracks", "source_layer": "GENERAL_GUIDANCE", "topcoat_role": [], "basecoat_role": [], "review_status": "approved", "warning_signs": ["διεύρυνση", "μετατόπιση", "επανεμφάνιση", "πολλαπλές ρωγμές"], "typical_causes": [], "evidence_status": "partial", "problem_type_id": "bd62cc86-1918-40d5-ab6a-8bf64f327415", "repair_sequence": [], "visual_symptoms": ["λεπτή γραμμική ρωγμή"], "solution_type_id": "c1e33d7a-770e-456b-83b9-c592f153cef2", "customer_title_el": "Εξωτερική βαφή με τριχοειδείς ρωγμές", "interior_exterior": "exterior", "technical_summary": "A visible crack is an observation, not proof of cause. Recurrent, widening, displaced or otherwise suspicious cracking should not be hidden by a coating-only recommendation.", "uv_considerations": [], "required_prechecks": ["