GENERAL_GUIDANCE", "technical_rule": "Remove loose material back to a stable substrate.", "evidence_strength": "strong_consensus", "conditional_expression": {}, "customer_explanation_el": "Αφαίρεσε τον σαθρό σοβά μέχρι σταθερή βάση.", "next_allowed_step_numbers": [4], "prerequisite_step_numbers": [2]}, {"id": "d1b70360-64d6-42d8-bbbb-905d23fcfaac", "active": true, "required": true, "step_type": "clean", "created_at": "2026-09-21T09:25:08.555464+00:00", "scenario_id": "ee32cf6b-39bd-4f26-87fd-1ae753392e3e", "step_number": 4, "source_layer": "GENERAL_GUIDANCE", "technical_rule": "Clean dust and debris from the repair area.", "evidence_strength": "strong_consensus", "conditional_expression": {}, "customer_explanation_el": "Καθάρισε σκόνη και υπολείμματα.", "next_allowed_step_numbers": [5], "prerequisite_step_numbers": [3]}, {"id": "fcaf3a07-ef6f-408c-9e04-4f161afea55e", "active": true, "required": true, "step_type": "repair", "created_at": "2026-09-21T09:25:08.555464+00:00", "scenario_id": "ee32cf6b-39bd-4f26-87fd-1ae753392e3e", "step_number": 5, "source_layer": "GENERAL_GUIDANCE", "technical_rule": "Apply a repair plaster/mortar compatible with substrate, depth and exposure.", "evidence_strength": "context_dependent", "conditional_expression": {}, "customer_explanation_el": "Εφάρμοσε επισκευαστικό κατάλληλο για βάση, βάθος και συνθήκες.", "next_allowed_step_numbers": [6], "prerequisite_step_numbers": [4]}, {"id": "f19844ea-eb9a-4352-ae12-8db2726bd159", "active": true, "required": true, "step_type": "cure", "created_at": "2026-09-21T09:25:08.555464+00:00", "scenario_id": "ee32cf6b-39bd-4f26-87fd-1ae753392e3e", "step_number": 6, "source_layer": "GENERAL_GUIDANCE", "technical_rule": "Allow the repair to cure/dry as required by its manufacturer before finishing.", "evidence_strength": "context_dependent", "conditional_expression": {}, "customer_explanation_el": "Άφησε την επισκευή να ωριμάσει/στεγνώσει όσο απαιτεί το προϊόν.", "next_allowed_step_numbers": [7], "prerequisite_step_numbers": [5]}, {"id": "dc949f60-fc2c-438b-9c6a-85df576df03d", "active": true, "required": false, "step_type": "level_and_prepare_finish", "created_at": "2026-09-21T09:25:08.555464+00:00", "scenario_id": "ee32cf6b-39bd-4f26-87fd-1ae753392e3e", "step_number": 7, "source_layer": "GENERAL_GUIDANCE", "technical_rule": "Level/sand and remove dust as appropriate before finish.", "evidence_strength": "common_professional_practice", "conditional_expression": {"finish_required": true}, "customer_explanation_el": "Εξομάλυνε/τρίψε όπου χρειάζεται και αφαίρεσε τη σκόνη.", "next_allowed_step_numbers": [8], "prerequisite_step_numbers": [6]}, {"id": "92745643-c96d-41e6-82a9-16eb05672711", "active": true, "required": false, "step_type": "prime_and_finish", "created_at": "2026-09-21T09:25:08.555464+00:00", "scenario_id": "ee32cf6b-39bd-4f26-87fd-1ae753392e3e", "step_number": 8, "source_layer": "GENERAL_GUIDANCE", "technical_rule": "Prime and finish according to a compatible coating system.", "evidence_strength": "context_dependent", "conditional_expression": {"finish_required": true}, "customer_explanation_el": "Αστάρωσε και βάψε με συμβατό σύστημα.", "next_allowed_step_numbers": [9], "prerequisite_step_numbers": [7]}, {"id": "981c0565-ff85-484d-a37f-42bc016778ba", "active": true, "required": true, "step_type": "inspect", "created_at": "2026-09-21T09:25:08.555464+00:00", "scenario_id": "ee32cf6b-39bd-4f26-87fd-1ae753392e3e", "step_number": 9, "source_layer": "GENERAL_GUIDANCE", "technical_rule": "Inspect for cracking, detachment and moisture recurrence after curing.", "evidence_strength": "common_professional_practice", "conditional_expression": {}, "customer_explanation_el": "Έλεγξε για ρωγμές, αποκόλληση και νέα υγρασία.", "next_allowed_step_numbers": [], "prerequisite_step_numbers": [8]}, {"id": "8abfced5-b93d-42f6-bfd8-6fe11c315346", "active": true, "required": true, "step_type": "diagnose", "created_at": "2026-09-21T09:25:08.555464+00:00", "scenario_id": "fb76f049-3915-