ustomer_explanation_el": "Βάλε αστάρι μόνο όταν το απαιτεί η κατάσταση της βάσης ή το επιλεγμένο σύστημα.", "next_allowed_step_numbers": [8], "prerequisite_step_numbers": [6]}, {"id": "c040ba1b-39ab-4023-8e9c-72380775b32c", "active": true, "required": true, "step_type": "finish_coating", "created_at": "2026-09-21T09:25:08.555464+00:00", "scenario_id": "fb76f049-3915-4e45-b35b-1aa7fbe94e4c", "step_number": 8, "source_layer": "GENERAL_GUIDANCE", "technical_rule": "Apply the selected finish coating strictly according to verified manufacturer instructions.", "evidence_strength": "context_dependent", "conditional_expression": {}, "customer_explanation_el": "Εφάρμοσε το τελικό χρώμα σύμφωνα με τις επαληθευμένες οδηγίες του κατασκευαστή.", "next_allowed_step_numbers": [9], "prerequisite_step_numbers": [7]}, {"id": "798f1106-962c-4640-94d0-e61a910b2c1b", "active": true, "required": true, "step_type": "cure", "created_at": "2026-09-21T09:25:08.555464+00:00", "scenario_id": "fb76f049-3915-4e45-b35b-1aa7fbe94e4c", "step_number": 9, "source_layer": "GENERAL_GUIDANCE", "technical_rule": "Observe manufacturer drying, recoat and cure requirements.", "evidence_strength": "context_dependent", "conditional_expression": {}, "customer_explanation_el": "Τήρησε τους χρόνους στεγνώματος, επαναβαφής και ωρίμανσης του προϊόντος.", "next_allowed_step_numbers": [10], "prerequisite_step_numbers": [8]}, {"id": "1a25c5a4-4a34-40c8-b977-b451b18f8b74", "active": true, "required": true, "step_type": "inspect", "created_at": "2026-09-21T09:25:08.555464+00:00", "scenario_id": "fb76f049-3915-4e45-b35b-1aa7fbe94e4c", "step_number": 10, "source_layer": "GENERAL_GUIDANCE", "technical_rule": "Inspect the cured result for adhesion, uniformity and recurrence of the original defect.", "evidence_strength": "common_professional_practice", "conditional_expression": {}, "customer_explanation_el": "Μετά την ωρίμανση, έλεγξε πρόσφυση, ομοιομορφία και αν επανεμφανίζεται το αρχικό πρόβλημα.", "next_allowed_step_numbers": [], "prerequisite_step_numbers": [9]}]$kmseed$::jsonb)
