INSERT INTO public.build_stop_conditions
SELECT * FROM jsonb_populate_recordset(NULL::public.build_stop_conditions, $kmseed$[{"id": "87863b47-9fce-47c6-88c0-1ed01a2c1074", "active": true, "severity": "BLOCK", "stop_key": "active_water_ingress", "reason_el": "Υπάρχει ενεργή εισροή νερού. Η διακοσμητική βαφή ή μια τυχαία στεγανωτική επάλειψη δεν πρέπει να παρουσιαστεί ως λύση της αιτίας.", "created_at": "2026-09-21T09:19:44.151992+00:00", "updated_at": "2026-09-21T09:19:44.151992+00:00", "scenario_id": null, "source_layer": "KONTA_MOU_RULE", "evidence_basis": "WHO dampness guidance; EOTA waterproofing system guidance.", "next_action_el": "Εντόπισε και αντιμετώπισε πρώτα την πηγή/διαδρομή του νερού. Αν δεν είναι σαφής, χρειάζεται τεχνικός έλεγχος.", "condition_expression": {"active_water_ingress": true}, "professional_assessment_required": true}, {"id": "a05b1f67-9e42-4004-85a4-7e7691b9649d", "active": true, "severity": "BLOCK", "stop_key": "guidance_conflict", "reason_el": "Η γενική καθοδήγηση και η τεκμηριωμένη οδηγία του επιλεγμένου προϊόντος φαίνεται να συγκρούονται.", "created_at": "2026-09-21T09:19:44.151992+00:00", "updated_at": "2026-09-21T09:19:44.151992+00:00", "scenario_id": null, "source_layer": "KONTA_MOU_RULE", "evidence_basis": "KONTA MOU truth-layer governance rule.", "next_action_el": "Μην κάνεις αυτόματη συμφιλίωση. Σήμανε τη σύγκρουση για τεχνικό έλεγχο και κράτησε τις δύο πηγές χωριστές.", "condition_expression": {"guidance_conflict": true}, "professional_assessment_required": true}, {"id": "cfcbe420-ed6d-4290-b8ab-12215299f2bb", "active": true, "severity": "BLOCK", "stop_key": "manufacturer_application_data_missing", "reason_el": "Έχει επιλεγεί συγκεκριμένο προϊόν αλλά δεν υπάρχουν επαληθευμένες οδηγίες κατασκευαστή για την εφαρμογή του.", "created_at": "2026-09-21T09:19:44.151992+00:00", "updated_at": "2026-09-21T09:19:44.151992+00:00", "scenario_id": null, "source_layer": "KONTA_MOU_RULE", "evidence_basis": "KONTA MOU truth-layer rule. Exact product instructions belong exclusively to verified manufacturer evidence.", "next_action_el": "Δείξε μόνο γενική τεχνική καθοδήγηση. Μην εμφανίσεις ακριβή αραίωση, αριθμό στρώσεων, κατανάλωση, χρόνους ή περιβαλλοντικά όρια μέχρι να επαληθευτούν.", "condition_expression": {"exact_product_selected": true, "manufacturer_verified_application_profile": false}, "professional_assessment_required": false}, {"id": "d70d6b88-e01b-4af9-9c8d-3eb9f234cc5b", "active": true, "severity": "BLOCK", "stop_key": "progressive_or_displaced_crack", "reason_el": "Η ρωγμή μεγαλώνει, επανέρχεται ή παρουσιάζει μετατόπιση. Δεν πρέπει να αντιμετωπιστεί ως απλή αισθητική ρωγμή.", "created_at": "2026-09-21T09:19:44.151992+00:00", "updated_at": "2026-09-21T09:19:44.151992+00:00", "scenario_id": null, "source_layer": "KONTA_MOU_RULE", "evidence_basis": "Conservative KONTA MOU rule supported by professional/government building-maintenance guidance on progressive movement.", "next_action_el": "Ζήτησε τεχνική αξιολόγηση πριν κλείσεις ή καλύψεις τη ρωγμή.", "condition_expression": {"crack_progressive_or_displaced": true}, "professional_assessment_required": true}, {"id": "4d69e36b-4cef-46ad-9df8-a859195c5d61", "active": true, "severity": "BLOCK", "stop_key": "roof_ponding_unresolved", "reason_el": "Τα λιμνάζοντα νερά δεν έχουν αξιολογηθεί ως προς κλίσεις και απορροές. Η νέα στεγάνωση από μόνη της δεν διορθώνει απαραίτητα την αιτία.", "created_at": "2026-09-21T09:19:44.151992+00:00", "updated_at": "2026-09-21T09:19:44.151992+00:00", "scenario_id": null, "source_layer": "KONTA_MOU_RULE", "evidence_basis": "LRWA flat-roof falls guidance and EN 12056-3 roof-drainage scope.", "next_action_el": "Έλεγξε κλίσεις, παραμορφώσεις και λειτουργία απορροών πριν επιλεγεί στεγανωτικό σύστημα.", "condition_expression": {"standing_water": true, "drainage_or_falls_assessed": false}, "professional_assessment_required": true}, {"id": "7348e5a3-d600-4c23-a3a6-036ef747183d", "active": true, "severity": "BLOCK", "stop_key": "severe_or_persistent_mould", "reason_el": "Η μούχλα είναι εκτεταμένη, επίμονη ή επανέρχεται. Η απλή βαφή δεν αντιμετωπίζει την πηγή υγρασίας.", "created_at": "2026-09-21T09:19:44.151992+00:00", "updated_at": "2026-09-21T09:19:44.151992+00:00", "scenario_id": null, "source_layer": "KONTA_MOU_RULE", "evidence_basis": "WHO and EPA moisture/mould guidance.", "next_action_el": "Αποκατάστησε την αιτία υγρασίας και χρησιμοποίησε κατάλληλη επαγγελματική αξιολόγηση/αποκατάσταση όπου απαιτείται.", "condition_expression": {"mould_severity": "severe_or_persistent"}, "professional_assessment_required": true}, {"id": "7ad84cc3-fa41-44aa-8f32-790a26cdbaf2", "active": true, "severity": "BLOCK", "stop_key": "significant_moisture_source_uncertain", "reason_el": "Η σημαντική υγρασία έχει αβέβαιη αιτία. Δεν είναι ασφαλές να επιλεγεί τελικό coating μόνο από το ορατό σύμπτωμα.", "created_at": "2026-09-21T09:19:44.151992+00:00", "updated_at": "2026-09-21T09:19:44.151992+00:00", "scenario_id": null, "source_layer": "KONTA_MOU_RULE", "evidence_basis": "WHO dampness and mould guidance; ISO 13788 / TEE thermal-bridge guidance for condensation-related cases.", "next_action_el": "Διερεύνησε αν πρόκειται για συμπύκνωση, διαρροή, βροχή, ανερχόμενη υγρασία ή άλλη πηγή πριν συνεχίσεις.", "condition_expression": {"source_known": false, "significant_moisture": true}, "professional_assessment_required": true}, {"id": "76300706-1165-4fc9-ae90-79a966706c1f", "active": true, "severity": "BLOCK", "stop_key": "suspected_structural_concrete_damage", "reason_el": "Υπάρχουν ενδείξεις που μπορεί να αφορούν δομικό στοιχείο, όπως αποκόλληση σκυροδέματος ή εμφανής/διαβρωμένος οπλισμός.", "created_at": "2026-09-21T09:19:44.151992+00:00", "updated_at": "2026-09-21T09:19:44.151992+00:00", "scenario_id": null, "source_layer": "KONTA_MOU_RULE", "evidence_basis": "KONTA MOU safety rule; avoids presenting a cosmetic repair as structural diagnosis.", "next_action_el": "Μην συνεχίσεις με απλό repair/paint workflow. Χρειάζεται τεχνική αξιολόγηση.", "condition_expression": {"suspected_structural_concrete_damage": true}, "professional_assessment_required": true}, {"id": "5d1ac767-6ffb-4b4a-a3f3-6b0a70d87f75", "active": true, "severity": "WARN", "stop_key": "unknown_existing_coating_compatibility", "reason_el": "Η υπάρχουσα επίστρωση δεν έχει ταυτοποιηθεί ή η συμβατότητα δεν είναι επιβεβαιωμένη.", "created_at": "2026-09-21T09:19:44.151992+00:00", "updated_at": "2026-09-21T09:19:44.151992+00:00", "scenario_id": null, "source_layer": "KONTA_MOU_RULE", "evidence_basis": "General surface-preparation and compatibility practice.", "next_action_el": "Κάνε δοκιμή σε μικρή περιοχή ή χρησιμοποίησε τεχνική επιβεβαίωση του επιλεγμένου συστήματος πριν από γενική εφαρμογή.", "condition_expression": {"existing_coating_known_compatible": false}, "professional_assessment_required": false}, {"id": "4e1b7b67-05d9-4017-a5da-80ab7f3b15cb", "active": true, "severity": "BLOCK", "stop_key": "unsafe_work_at_height", "reason_el": "Η εργασία απαιτεί πρόσβαση σε ύψος χωρίς επιβεβαιωμένο ασφαλές σύστημα πρόσβασης/προστασίας από πτώση.", "created_at": "2026-09-21T09:19:44.151992+00:00", "updated_at": "2026-09-21T09:19:44.151992+00:00", "scenario_id": null, "source_layer": "KONTA_MOU_RULE", "evidence_basis": "EU-OSHA work-at-height guidance: risk assessment and fall prevention are required before work at height.", "next_action_el": "Μην προχωρήσεις ως DIY workflow. Οργάνωσε ασφαλή πρόσβαση και κατάλληλα μέτρα/εξοπλισμό από αρμόδιο άτομο.", "condition_expression": {"work_at_height": true, "safe_access_confirmed": false}, "professional_assessment_required": true}, {"id": "1f1169e1-1dec-4974-a517-95196ebdce0d", "active": true, "severity": "BLOCK", "stop_key": "unstable_substrate", "reason_el": "Η βάση είναι σαθρή ή αποκολλάται. Νέα βαφή, στόκος ή μεμβράνη πάνω σε ασταθή βάση έχει υψηλό κίνδυνο αστοχίας.", "created_at": "2026-09-21T09:19:44.151992+00:00", "updated_at": "2026-09-21T09:19:44.151992+00:00", "scenario_id": null, "source_layer": "KONTA_MOU_RULE", "evidence_basis": "Recognised painting/surface-preparation practice; BS 6150 scope and Sherwin-Williams general preparation guidance.", "next_action_el": "Αφαίρεσε τα ασταθή υλικά μέχρι σταθερή βάση και αξιολόγησε την απαιτούμενη επισκευή πριν από τελικό σύστημα.", "condition_expression": {"substrate_stable": false}, "professional_assessment_required": false}, {"id": "20229d2a-637e-4a32-a443-e28d2f4cca62", "active": true, "severity": "BLOCK", "stop_key": "widespread_detached_plaster", "reason_el": "Υπάρχει εκτεταμένη αποκόλληση επιχρίσματος ή κίνδυνος πτώσης υλικών.", "created_at": "2026-09-21T09:19:44.151992+00:00", "updated_at": "2026-09-21T09:19:44.151992+00:00", "scenario_id": null, "source_layer": "KONTA_MOU_RULE", "evidence_basis": "Conservative KONTA MOU safety rule; unstable/falling material cannot be treated as a cosmetic paint defect.", "next_action_el": "Περιορίστε την πρόσβαση όπου υπάρχει κίνδυνος και ζητήστε τεχνική αξιολόγηση της βάσης πριν από επισκευή/βαφή.", "condition_expression": {"detached_plaster": "widespread"}, "professional_assessment_required": true}]$kmseed$::jsonb)
