SELECT * FROM jsonb_populate_recordset(NULL::public.general_build_rule_evidence, $kmseed$[{"id": "ad018e94-b4a8-4a72-bf8e-a697a88cf36f", "active": true, "entity_id": "01e6623b-4b05-451a-a58e-4cefe5eb2fc4", "source_id": "06e1dba9-9365-4a5d-8e5f-0564d4df99d3", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "diagnostic_rule", "applicability": "General hygrothermal risk screening; detailed design may require a more complete assessment than ISO 13788 alone. Scenario: insulation_internal_condensation_risk.", "evidence_strength": "standard_based", "supporting_passage": "ISO 13788 provides methods to assess internal surface conditions associated with critical surface humidity and interstitial condensation, supporting condensation-risk assessment before selecting an internal-insulation solution.", "relevant_section_page": "Standard scope"}, {"id": "808bc980-2061-43a4-87eb-c8b902934136", "active": true, "entity_id": "3806b4be-6011-4df7-b1d4-111af6e53ae2", "source_id": "228fcd5a-dbaa-41e7-9aaf-1a9cd7266381", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "diagnostic_rule", "applicability": "General steel-preparation principle; exact preparation grade and coating system depend on the project/product specification. Scenario: paint_metal_rusty.", "evidence_strength": "context_dependent", "supporting_passage": "ISO 12944-4 addresses surface types and preparation of steel surfaces for corrosion-protective paint systems, supporting removal/preparation of corrosion and contaminants before coating.", "relevant_section_page": "Standard scope"}, {"id": "49987581-213b-4336-91ab-ce526c79cb91", "active": true, "entity_id": "3ac2ce9c-c14f-4da1-bfca-82506cd2116d", "source_id": "34563425-ac2b-4a6c-89f2-8bc4090678de", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "diagnostic_rule", "applicability": "General liquid-waterproofing inspection practice; exact selected system rules remain manufacturer-specific. Scenario: waterproof_flat_roof.", "evidence_strength": "standard_based", "supporting_passage": "LRWA guidance requires roof inspection, safe access, substrate identification, condition assessment, leak-source investigation, moisture assessment and inspection of drainage/details before specifying a liquid-applied waterproofing system.", "relevant_section_page": "Sections 2–5, pp. 1–4"}, {"id": "74c2b4d5-1ef7-4dcf-93bb-ea6d67942368", "active": true, "entity_id": "40da8232-3d94-498c-993e-fb7ebc79a5e4", "source_id": "c5efac2e-3bde-47b7-90d4-27341236d3c8", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "diagnostic_rule", "applicability": "Conservative crack screening only; no UK numerical threshold is used as a universal Greek rule. Scenario: paint_exterior_hairline_cracks.", "evidence_strength": "context_dependent", "supporting_passage": "RICS notes that visible cracks can require measurement/monitoring and that new or expanding cracks and other movement indicators warrant further investigation rather than automatic cosmetic treatment.", "relevant_section_page": "How can I tell if my house is subsiding?"}, {"id": "794329a0-ad9e-4492-8f95-b47525385cc2", "active": true, "entity_id": "5865ed2b-e290-4bea-adba-178b7c0084d3", "source_id": "c5efac2e-3bde-47b7-90d4-27341236d3c8", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "diagnostic_rule", "applicability": "General conservative screening only; exact repair-material limits remain manufacturer-specific. Scenario: repair_hairline_wall_crack.", "evidence_strength": "context_dependent", "supporting_passage": "RICS crack guidance supports distinguishing stable/cosmetic cracking from new or expanding movement indicators that may require monitoring or specialist investigation.", "relevant_section_page": "How can I tell if my house is subsiding?"}, {"id": "59ceb996-4436-4fd0-84c0-08bc9673d0ab", "active": true, "entity_id": "64990265-16ba-4346-beb5-cfc2dcaa9bb9", "source_id": "228fcd5a-dbaa-41e7-9aaf-1a9cd7266381", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "diagnostic_rule", "applicability": "General steel-preparation principle; exact preparation grade and coating system depend on the project/product specification. Scenario: paint_metal_rusty.", "evidence_strength": "standard_based", "supporting_passage": "ISO 12944-4 addresses surface types and preparation of steel surfaces for corrosion-protective paint systems, supporting removal/preparation of corrosion and contaminants before coating.", "relevant_section_page": "Standard scope"}, {"id": "bfdfeb1b-c063-4479-8afb-d2d8b10478e3", "active": true, "entity_id": "6a5dd8b8-894d-44da-9ce0-291c2f4f6550", "source_id": "8508b539-532b-476f-a1ec-068a60b91c77", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "diagnostic_rule", "applicability": "Ordinary non-structural repainting only; exact coating compatibility remains product-specific. Scenario: paint_interior_repaint_sound.", "evidence_strength": "strong_consensus", "supporting_passage": "General surface-preparation guidance requires a clean, sound and appropriately prepared existing surface before repainting.", "relevant_section_page": "Surface preparation"}, {"id": "01575953-8142-4229-a787-f145e4a37403", "active": true, "entity_id": "7629d904-8035-4f4a-b901-cde0735d3732", "source_id": "f3906f7a-9771-4857-b739-8d1bc8105e72", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "diagnostic_rule", "applicability": "General ETICS sequencing/system context only; exact component/product instructions remain manufacturer evidence. Scenario: insulation_external_etics.", "evidence_strength": "standard_based", "supporting_passage": "The EAE European Application Guideline treats ETICS as a complete system whose quality, safety and durability depend on correct system design and installation, with system-holder instructions also governing application.", "relevant_section_page": "European Application Guideline for ETICS"}, {"id": "fbba46e1-2279-4bfe-a022-9f01077d9f88", "active": true, "entity_id": "7c7cdf7f-cbc9-4d9b-ab5d-6682a20e9bdd", "source_id": "06e1dba9-9365-4a5d-8e5f-0564d4df99d3", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "diagnostic_rule", "applicability": "General hygrothermal risk screening; detailed design may require a more complete assessment than ISO 13788 alone. Scenario: insulation_internal_condensation_risk.", "evidence_strength": "standard_based", "supporting_passage": "ISO 13788 provides methods to assess internal surface conditions associated with critical surface humidity and interstitial condensation, supporting condensation-risk assessment before selecting an internal-insulation solution.", "relevant_section_page": "Standard scope"}, {"id": "dc0031f6-238e-4d1b-ae0b-1c7bbc68d280", "active": true, "entity_id": "7e605c59-a5ca-4471-b7b5-98d73eb5b4f7", "source_id": "f3906f7a-9771-4857-b739-8d1bc8105e72", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "diagnostic_rule", "applicability": "General ETICS sequencing/system context only; exact component/product instructions remain manufacturer evidence. Scenario: insulation_external_etics.", "evidence_strength": "standard_based", "supporting_passage": "The EAE European Application Guideline treats ETICS as a complete system whose quality, safety and durability depend on correct system design and installation, with system-holder instructions also governing application.", "relevant_section_page": "European Application Guideline for ETICS"}, {"id": "4a118fa9-45c0-4bd6-8cf9-a64c975846be", "active": true, "entity_id": "81b2af50-f795-4602-be0d-752b6ee9eb68", "source_id": "8508b539-532b-476f-a1ec-068a60b91c77", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "diagnostic_rule", "applicability": "Ordinary non-structural repainting only; exact system selection remains product-specific. Scenario: paint_exterior_repaint_sound.", "evidence_strength": "strong_consensus", "supporting_passage": "General surface-preparation guidance requires surfaces to be sound, clean and suitably prepared before painting and addresses removal/preparation of unsound existing coatings.", "relevant_section_page": "Surface preparation"}, {"id": "9f2ad1bc-7a08-4d02-910d-9338d728740a", "active": true, "entity_id": "88c72823-1dac-44e3-a0a8-6d29ff716909", "source_id": "141a3e27-7aa1-41f4-9a19-7d9185385618", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "diagnostic_rule", "applicability": "General moisture/mould guidance; extensive or uncertain cases are escalated rather than diagnosed by the Studio. Scenario: paint_interior_mould_damp.", "evidence_strength": "strong_consensus", "supporting_passage": "EPA guidance makes moisture control, correction of water problems, mould cleanup and complete drying prerequisites before painting mould-affected surfaces.", "relevant_section_page": "Basic mould cleanup steps"}, {"id": "f9b871cb-55b1-48ef-bca6-69e4e54e5fd7", "active": true, "entity_id": "b9de0036-8135-458b-b451-9e8025765e9f", "source_id": "25f57aab-d2d3-4986-bb22-600e7268ace4", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "diagnostic_rule", "applicability": "General painting practice; exact primer/topcoat and drying requirements remain manufacturer-specific. Scenario: paint_exterior_chalking.", "evidence_strength": "common_professional_practice", "supporting_passage": "Professional exterior-paint preparation guidance treats chalking as a surface-condition/adhesion issue requiring cleaning and preparation before recoating.", "relevant_section_page": "Exterior surface preparation — chalking"}, {"id": "008f96a4-ea0a-4dc9-a9bc-8b2664a693f2", "active": true, "entity_id": "c1bb02ef-d9a3-484e-936e-40195d40edf2", "source_id": "72337f4f-0492-4ac7-ad0a-424770c4bc11", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "diagnostic_rule", "applicability": "Ordinary non-structural wall repair only; widespread failure, moisture or structural indications require escalation. Scenario: repair_damaged_plaster.", "evidence_strength": "strong_consensus", "supporting_passage": "Professional wall-repair guidance removes loose/flaking material, repairs the substrate, allows repair material to dry, and prepares the repaired area before finishing.", "relevant_section_page": "Wall repair — preparation and patching"}, {"id": "f7c6849b-c64c-4abd-82a8-f15e3843f0a7", "active": true, "entity_id": "c23befb8-7267-49f9-9ba1-9a1fef83de00", "source_id": "141a3e27-7aa1-41f4-9a19-7d9185385618", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "diagnostic_rule", "applicability": "General moisture/mould guidance; extensive or uncertain cases are escalated rather than diagnosed by the Studio. Scenario: paint_interior_mould_damp.", "evidence_strength": "standard_based", "supporting_passage": "EPA guidance makes moisture control, correction of water problems, mould cleanup and complete drying prerequisites before painting mould-affected surfaces.", "relevant_section_page": "Basic mould cleanup steps"}, {"id": "3cb8a8e3-3213-4704-8a7e-9c886115070b", "active": true, "entity_id": "df2f4163-b8c0-4053-8969-53a2ac509cb2", "source_id": "d3d86175-0a94-4a12-93e0-3dae713325c9", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "diagnostic_rule", "applicability": "General wood-finishing principles; exact coating steps and environmental limits remain manufacturer-specific. Scenario: paint_wood_bare.", "evidence_strength": "strong_consensus", "supporting_passage": "The USDA Wood Handbook finishing chapter describes wood finishing as dependent on substrate condition, preparation, moisture/exposure and the selected finish system.", "relevant_section_page": "Wood Handbook, Chapter 16 — Finishing wood"}, {"id": "f9d1ef1c-aa28-4d5e-ae52-4ba96e8706b6", "active": true, "entity_id": "dff5d97c-7e97-43a1-8cd9-46c3c80ba95e", "source_id": "5779529c-513c-4ac6-989c-1727d0c3146f", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "diagnostic_rule", "applicability": "Stain 