 true, "entity_id": "83ab157f-5967-4104-b933-12e92753b0ef", "source_id": "25f57aab-d2d3-4986-bb22-600e7268ace4", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "profile", "applicability": "General painting practice; exact primer/topcoat and drying requirements remain manufacturer-specific. Scenario: paint_exterior_chalking.", "evidence_strength": "common_professional_practice", "supporting_passage": "Professional exterior-paint preparation guidance treats chalking as a surface-condition/adhesion issue requiring cleaning and preparation before recoating.", "relevant_section_page": "Exterior surface preparation — chalking"}, {"id": "1705dfef-9c53-43d9-b2cc-8596aa6cdc27", "active": true, "entity_id": "927e495a-d584-45fb-ba88-2bfa2f507b74", "source_id": "d3d86175-0a94-4a12-93e0-3dae713325c9", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "profile", "applicability": "General wood-finishing principles; exact coating steps and environmental limits remain manufacturer-specific. Scenario: paint_wood_bare.", "evidence_strength": "strong_consensus", "supporting_passage": "The USDA Wood Handbook finishing chapter describes wood finishing as dependent on substrate condition, preparation, moisture/exposure and the selected finish system.", "relevant_section_page": "Wood Handbook, Chapter 16 — Finishing wood"}, {"id": "d50b5a02-8d8d-42bf-8449-e1d1037f8d2c", "active": true, "entity_id": "ab6a7f01-46b7-4c8e-aebd-3e5b56aa38bf", "source_id": "f3906f7a-9771-4857-b739-8d1bc8105e72", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "profile", "applicability": "General ETICS sequencing/system context only; exact component/product instructions remain manufacturer evidence. Scenario: insulation_external_etics.", "evidence_strength": "strong_consensus", "supporting_passage": "The EAE European Application Guideline treats ETICS as a complete system whose quality, safety and durability depend on correct system design and installation, with system-holder instructions also governing application.", "relevant_section_page": "European Application Guideline for ETICS"}, {"id": "4ecdab0d-ab69-4af6-9c4a-1bec3e0912d3", "active": true, "entity_id": "ae5cce5a-7b6f-4c60-83fc-2d64110ae6a8", "source_id": "34563425-ac2b-4a6c-89f2-8bc4090678de", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "profile", "applicability": "General liquid-waterproofing inspection practice; UK regulatory references are not treated as Greek law and exact system application remains manufacturer-specific. Scenario: waterproof_balcony_leak.", "evidence_strength": "strong_consensus", "supporting_passage": "LRWA guidance requires inspection of balcony/roof construction, substrate, membrane condition, drains, joints, cracks, flashings and other details; where leaking, the water-ingress source must be investigated before repair/specification.", "relevant_section_page": "Sections 3–5, pp. 2–4"}, {"id": "9fa5beb1-a406-41d0-bf28-7be47c702470", "active": true, "entity_id": "b825a11b-a846-4ff6-b636-6fae2853c43f", "source_id": "c5efac2e-3bde-47b7-90d4-27341236d3c8", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "profile", "applicability": "Conservative crack screening only; no UK numerical threshold is used as a universal Greek rule. Scenario: paint_exterior_hairline_cracks.", "evidence_strength": "context_dependent", "supporting_passage": "RICS notes that visible cracks can require measurement/monitoring and that new or expanding cracks and other movement indicators warrant further investigation rather than automatic cosmetic treatment.", "relevant_section_page": "How can I tell if my house is subsiding?"}, {"id": "22b471eb-a63f-4cce-8541-8ad36011623c", "active": true, "entity_id": "ccba9580-8065-4b4d-b676-37bba18998bf", "source_id": "8508b539-532b-476f-a1ec-068a60b91c77", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "profile", "applicability": "Ordinary non-structural repainting only; exact system selection remains product-specific. Scenario: paint_exterior_repaint_sound.", "evidence_strength": "common_professional_practice", "supporting_passage": "General surface-preparation guidance requires surfaces to be sound, clean and suitably prepared before painting and addresses removal/preparation of unsound existing coatings.", "relevant_section_page": "Surface preparation"}, {"id": "88d358b1-795f-4967-bef3-e29775500664", "active": true, "entity_id": "cf3640e9-904c-406d-b684-1c7661678eb3", "source_id": "06e1dba9-9365-4a5d-8e5f-0564d4df99d3", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "profile", "applicability": "General hygrothermal risk screening; detailed design may require a more complete assessment than ISO 13788 alone. Scenario: insulation_internal_condensation_risk.", "evidence_strength": "standard_based", "supporting_passage": "ISO 13788 provides methods to assess internal surface conditions associated with critical surface humidity and interstitial condensation, supporting condensation-risk assessment before selecting an internal-insulation solution.", "relevant_section_page": "Standard scope"}, {"id": "fa40d2c7-6642-4ccf-bef3-4c29770800ca", "active": true, "entity_id": "dc9278b0-e712-482d-ab3f-48d4ddde8bbf", "source_id": "34563425-ac2b-4a6c-89f2-8bc4090678de", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "profile", "applicability": "General liquid-waterproofing inspection practice; exact selected system rules remain manufacturer-specific. Scenario: waterproof_flat_roof.", "evidence_strength": "strong_consensus", "supporting_passage": "LRWA guidance requires roof inspection, safe access, substrate identification, condition assessment, leak-source investigation, moisture assessment and inspection of drainage/details before specifying a liquid-applied waterproofing system.", "relevant_section_page": "Sections 2–5, pp. 1–4"}, {"id": "fdb446de-54bd-4e18-99f3-20b224ec2a0f", "active": true, "entity_id": "ee32cf6b-39bd-4f26-87fd-1ae753392e3e", "source_id": "72337f4f-0492-4ac7-ad0a-424770c4bc11", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "profile", "applicability": "Ordinary non-structural wall repair only; widespread failure, moisture or structural indications require escalation. Scenario: repair_damaged_plaster.", "evidence_strength": "common_professional_practice", "supporting_passage": "Professional wall-repair guidance removes loose/flaking material, repairs the substrate, allows repair material to dry, and prepares the repaired area before finishing.", "relevant_section_page": "Wall repair — preparation and patching"}, {"id": "4ea405e0-5027-47d7-8da9-ec430e3bd235", "active": true, "entity_id": "fb76f049-3915-4e45-b35b-1aa7fbe94e4c", "source_id": "8508b539-532b-476f-a1ec-068a60b91c77", "created_at": "2026-09-21T10:18:58.0713+00:00", "entity_type": "profile", "applicability": "Ordinary non-structural repainting only; exact coating compatibility remains product-specific. Scenario: paint_interior_repaint_sound.", "evidence_strength": "common_professional_practice", "supporting_passage": "General surface-preparation guidance requires a clean, sound and appropriately prepared existing surface before repainting.", "relevant_section_page": "Surface preparation"}, {"id": "d27522bc-b779-449e-90d2-49263b8bab4a", "active": true, "entity_id": "01cdf330-ab28-430d-b5c8-24b77ec2e345", "source_id": "141a3e27-7aa1-41f4-9a19-7d9185385618", "created_at": "2026-09-21T10:21:22.404499+00:00", "entity_type": "project_kit_requirement", "applicability": "Supports moisture-remediation and conditional post-remediation coating slots. Scenario: paint_interior_mould_damp.", "evidence_strength": "strong_consensus", "supporting_passage": "EPA guidance requires fixing the moisture problem, cleaning/remediating mould and drying the surface before painting rather than painting over active mould.", "relevant_section_page": "Basic mould cleanup steps"}, {"id": "d1cbc542-0c4a-41ae-8c89-404b7f5b7428", "active": true, "entity_id": "01cdf330-ab28-430d-b5c8-24b77ec2e345", "source_id": "3829ce05-0552-4545-84f5-f4ecb76bb00a", "created_at": "2026-09-21T10:21:22.404499+00:00", "entity_type": "project_kit_requirement", "applicability": "Internal truth-layer boundary for product-specific quantity/compatibility fields.", "evidence_strength": "strong_consensus", "supporting_passage": "KONTA MOU governance requires exact consumption, coat/layer count, product compatibility and system-component approval to come from verified manufacturer evidence.", "relevant_section_page": "Manufacturer-boundary rule"}, {"id": "b0d36cf4-cc17-4738-ad06-1ee18c064483", "active": true, "entity_id": "067ec617-188c-4698-ab1e-81cd0fb0b78f", "source_id": "3829ce05-0552-4545-84f5-f4ecb76bb00a", "created_at": "2026-09-21T10:21:22.404499+00:00", "entity_type": "project_kit_requirement", "applicability": "Internal truth-layer boundary for product-specific quantity/compatibility fields.", "evidence_strength": "strong_consensus", "supporting_passage": "KONTA MOU governance requires exact consumption, coat/layer count, product compatibility and system-component approval to come from verified manufacturer evidence.", "relevant_section_page": "Manufacturer-boundary rule"}, {"id": "17251833-1601-432f-8a6a-531ac1acfac5", "active": true, "entity_id": "067ec617-188c-4698-ab1e-81cd0fb0b78f", "source_id": "5779529c-513c-4ac6-989c-1727d0c3146f", "created_at": "2026-09-21T10:21:22.404499+00:00", "entity_type": "project_kit_requirement", "applicability": "Supports generic project-kit slots; exact primer/coating/tool requirements remain manufacturer-specific. Scenario: paint_interior_new_plaster.", "evidence_strength": "standard_based", "supporting_passage": "BS 6150 provides the recognised painting-of-buildings framework in which substrate condition, preparation and the coating system are considered before application.", "relevant_section_page": "Standard scope / preparation framework"}, {"id": "3bcb3cf7-31cf-4246-bb9f-ace1