ity_id": "162ecb88-eb06-41fd-b844-3cf007371bc8", "source_id": "971e5893-7641-4b0e-aff9-792c98aa4223", "created_at": "2026-09-21T10:21:22.404499+00:00", "entity_type": "project_kit_requirement", "applicability": "Supports system/component slots; exact layer build-up requires project-specific design. Scenario: insulation_internal_condensation_risk.", "evidence_strength": "strong_consensus", "supporting_passage": "IWI best-practice guidance requires the insulation build-up, adhesives/finishes, air barrier and any vapour-control strategy to be consistent with the retrofit design and moisture strategy.", "relevant_section_page": "Moisture management and installation principles, pp. 41–43"}, {"id": "a527f849-7187-484b-9f38-fcfd85e0c00f", "active": true, "entity_id": "19f2603b-7285-4d01-a999-dfebcf3995bc", "source_id": "228fcd5a-dbaa-41e7-9aaf-1a9cd7266381", "created_at": "2026-09-21T10:21:22.404499+00:00", "entity_type": "project_kit_requirement", "applicability": "Exact coating layers and products depend on the selected protective system/specification. Scenario: paint_metal_rusty.", "evidence_strength": "standard_based", "supporting_passage": "ISO 12944-4 places steel surface preparation within a protective paint-system context, supporting preparation, primer and subsequent protective-coating stages.", "relevant_section_page": "Standard scope"}, {"id": "79aef36c-eaf5-4d05-94de-80edfd3a1738", "active": true, "entity_id": "19f2603b-7285-4d01-a999-dfebcf3995bc", "source_id": "3829ce05-0552-4545-84f5-f4ecb76bb00a", "created_at": "2026-09-21T10:21:22.404499+00:00", "entity_type": "project_kit_requirement", "applicability": "Internal truth-layer boundary for product-specific quantity/compatibility fields.", "evidence_strength": "strong_consensus", "supporting_passage": "KONTA MOU governance requires exact consumption, coat/layer count, product compatibility and system-component approval to come from verified manufacturer evidence.", "relevant_section_page": "Manufacturer-boundary rule"}, {"id": "c8d8df4b-7a96-4e79-a593-3140421b19c6", "active": true, "entity_id": "1b39f084-93ea-404a-8b64-0754e7a4b4bb", "source_id": "1d123881-3597-40c5-848c-32908fcb4961", "created_at": "2026-09-21T10:21:22.404499+00:00", "entity_type": "project_kit_requirement", "applicability": "Supports system kit model; exact kit composition remains manufacturer-specific. Scenario: waterproof_flat_roof.", "evidence_strength": "strong_consensus", "supporting_passage": "LRWA guidance treats liquid roof waterproofing as a specified system with preparation, optional primers/reinforcement/repairs, application method, compatible accessories and quality control.", "relevant_section_page": "Section 5 Workmanship"}, {"id": "1c05c133-db6d-4cb8-b81d-d339a666e633", "active": true, "entity_id": "1b39f084-93ea-404a-8b64-0754e7a4b4bb", "source_id": "3829ce05-0552-4545-84f5-f4ecb76bb00a", "created_at": "2026-09-21T10:21:22.404499+00:00", "entity_type": "project_kit_requirement", "applicability": "Internal truth-layer boundary for product-specific quantity/compatibility fields.", "evidence_strength": "strong_consensus", "supporting_passage": "KONTA MOU governance requires exact consumption, coat/layer count, product compatibility and system-component approval to come from verified manufacturer evidence.", "relevant_section_page": "Manufacturer-boundary rule"}, {"id": "ace9a7fa-7512-4263-9405-027d33abdb5a", "active": true, "entity_id": "1c0438a7-9aa5-4ced-b3e0-6db003de25bc", "source_id": "f3906f7a-9771-4857-b739-8d1bc8105e72", "created_at": "2026-09-21T10:21:22.404499+00:00", "entity_type": "project_kit_requirement", "applicability": "Supports project-kit component slots as a system; exact components/quantities remain manufacturer/design specific. Scenario: insulation_external_etics.", "evidence_strength": "strong_consensus", "supporting_passage": "EAE treats ETICS as a system whose components and installation must remain consistent with the system holder’s specification and installation