id": "5779529c-513c-4ac6-989c-1727d0c3146f", "created_at": "2026-09-21T10:21:22.404499+00:00", "entity_type": "project_kit_requirement", "applicability": "Supports generic project-kit slots; exact primer/coating/tool requirements remain manufacturer-specific. Scenario: paint_interior_new_plaster.", "evidence_strength": "standard_based", "supporting_passage": "BS 6150 provides the recognised painting-of-buildings framework in which substrate condition, preparation and the coating system are considered before application.", "relevant_section_page": "Standard scope / preparation framework"}, {"id": "5de93113-02c8-41a1-91dc-b55ecb03fe8b", "active": true, "entity_id": "03964ecf-7b62-4c41-9486-310fcd4bd4d5", "source_id": "c92a4d9b-2332-494d-837c-127a914fc90a", "created_at": "2026-09-21T09:40:57.103749+00:00", "entity_type": "solution_rule", "applicability": "paint_metal_rusty — Supports project-specific assessment of steel surface condition and preparation grade.", "evidence_strength": "standard_based", "supporting_passage": "ISO 8501-1 provides visual rust grades and preparation grades for steel surfaces before application of paints and related products.", "relevant_section_page": "Abstract / rust and preparation grades"}, {"id": "b2aa0cc1-9f19-4447-a48e-f4e8c653ad5e", "active": true, "entity_id": "05cf6826-3a39-4bf1-8425-6d2a9c02425d", "source_id": "5ef44a5a-f6fe-44e4-b703-6dc86e02948e", "created_at": "2026-09-21T09:40:57.103749+00:00", "entity_type": "solution_rule", "applicability": "waterproof_roof_standing_water — Supports why KONTA MOU must not use one universal coverage or waste factor; the selected product declaration remains the calculation basis.", "evidence_strength": "strong_consensus", "supporting_passage": "Hempel distinguishes theoretical from practical consumption and states that practical consumption varies with film waviness, surface size/shape, substrate roughness and physical losses.", "relevant_section_page": "Practical consumption / Consumption Factor"}, {"id": "7626543d-490d-4872-bb64-716162a59f65", "active": true, "entity_id": "085faf4e-715a-4897-92e3-f3e7ae7a9b60", "source_id": "8508b539-532b-476f-a1ec-068a60b91c77", "created_at": "2026-09-21T09:40:57.103749+00:00", "entity_type": "solution_rule", "applicability": "paint_exterior_repaint_sound — General preparation principle; exact product preparation remains Layer B.", "evidence_strength": "common_professional_practice", "supporting_passage": "General surface-preparation guidance requires removal of contaminants and loose material and a sound, clean substrate before coating.", "relevant_section_page": "General surface preparation"}, {"id": "3572df17-b4dc-4a2d-aec9-ca8bfb41dc7a", "active": true, "entity_id": "0d1ab120-ed9c-4a8a-b87c-967f482951bd", "source_id": "5efe64a0-4dea-44a6-a662-0aeaba6fcbe9", "created_at": "2026-09-21T09:40:57.103749+00:00", "entity_type": "solution_rule", "applicability": "paint_interior_stained — Supports screening a stain for active moisture before cosmetic treatment.", "evidence_strength": "strong_consensus", "supporting_passage": "RICS guidance states that damp has multiple possible moisture sources and that the source of excess moisture should be found before remediation.", "relevant_section_page": "Damp sources / find the moisture source"}, {"id": "6d659045-9b69-4130-b044-19cbd4d1d191", "active": true, "entity_id": "0d3b18ac-e4f6-40b0-81ec-a2f26c9ef136", "source_id": "5779529c-513c-4ac6-989c-1727d0c3146f", "created_at": "2026-09-21T09:40:57.103749+00:00", "entity_type": "solution_rule", "applicability": "paint_interior_new_plaster — General readiness principle only; exact moisture/pH/cure limits come from applicable system documentation.", "evidence_strength": "strong_consensus", "supporting_passage": "Painting-of-buildings practice covers preparation of new substrates before initial painting; unstable, damp or unready substrate should not be treated as a finished coating base.", "relevant_section_page": "Scope: preparation an